import jinja2

template = """&lt;h2&gt;{{ event }}&lt;/h2&gt;
&lt;p&gt;&lt;script&gt; var msg = '{{ message }}'&lt;/script&gt;&lt;/p&gt;"""

env = jinja2.Environment()
env.autoescape = False

def render_event(event, message):
    return env.from_string(template).render(event=event, message=message)

